import numpy as np, zlib
docs = {"a": "the quick brown fox jumps over the lazy dog today",
        "b": "the quick brown fox jumps over the lazy dog again",
        "c": "the quick brown fox leaps over the lazy cat today",
        "d": "language models need clean and deduplicated data"}
def shingles(t, k=3):                      # 단어 3-gram 집합
    w = t.split(); return {" ".join(w[i:i+k]) for i in range(len(w)-k+1)}
S = {k: {zlib.crc32(s.encode()) for s in shingles(v)} for k, v in docs.items()}
def jaccard(A, B): return len(A & B) / len(A | B)
P, n = (1 << 61) - 1, 200                  # 해시 h(x) = (a·x + c) mod P 를 n 개
rng = np.random.default_rng(0)
a, c = rng.integers(1, P, n, dtype=np.int64), rng.integers(0, P, n, dtype=np.int64)
def signature(s):
    x = np.array(sorted(s), dtype=object)
    return np.array([min((int(ai) * xi + int(ci)) % P for xi in x) for ai, ci in zip(a, c)], dtype=object)
sig = {k: signature(v) for k, v in S.items()}
for p, q in [("a", "b"), ("a", "c"), ("a", "d")]:
    print(p, q, f"실제 J={jaccard(S[p], S[q]):.3f}  MinHash 추정={np.mean(sig[p] == sig[q]):.3f}")
b, r = 20, 10                               # LSH: 밴드 20 × 행 10 = 200
buckets = {}
for k, s in sig.items():
    for i in range(b):
        buckets.setdefault((i, tuple(s[i*r:(i+1)*r])), set()).add(k)
print("후보 쌍:", sorted({tuple(sorted(v)) for v in buckets.values() if len(v) > 1}))
